  await click('[data-testid="config-reset-tomcat"]');
  await sleep(200);
  /** The draft as the clipboard receives it, split back into its labelled files. */
  async function copyAll() {
    app.clearClipboard();
    await clickFooter("复制全部");
    await until(() => app.readClipboard() !== null, "the copied draft");
    await untilNotice("已复制", "the copy to finish");
    const text = app.readClipboard();
    const files = {};
    for (const match of text.matchAll(/===== BEGIN (\S+) =====\n([\s\S]*?)===== END \1 =====\n\n/gu)) files[match[1]] = match[2];
    return { text, files, order: Object.keys(files) };
  }
