  const pgReturned = { features: await checked("postgresql"), version: await version("postgresql") };
  await click('[data-testid="config-reset-postgresql"]');
  await sleep(200);
  const pgReset = { features: await checked("postgresql"), fields: await fields(), version: await version("postgresql") };
  const pgRegenerated = (await generate()).text;
  const pgName = await draftName();
