  const mariaSaved = await exportTwice(path.join(exportDirectory, "mariadb-quick.cnf"));
  const mariaVisual = await openVisualStatus();
  await shot("mariadb-option-file-visual");
  await toGenerator("mariadb");
  await click('[data-testid="config-reset-mariadb"]');
